import{_ as e,o as t,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse(`{"title":"HJ57 高精度整数加法","description":"中等 通过率：35.40% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 输入两个用字符串 str 表示的整数，求它们所表示的数之和。 数据范围： 1≤���(���)≤10000 1≤ len ( str )≤10000 输入描述： 输入两个字符串。保证字符串只含有'。","frontmatter":{"title":"HJ57 高精度整数加法","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：35.40% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 输入两个用字符串 str 表示的整数，求它们所表示的数之和。 数据范围： 1≤���(���)≤10000 1≤ len ( str )≤10000 输入描述： 输入两个字符串。保证字符串只含有'。","sidebarWeight":58,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ57 高精度整数加法.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ57 高精度整数加法.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ57 高精度整数加法.md"}`),o={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ57 高精度整数加法.md"};function i(l,a,s,d,u,p){return t(),r("div",null,[...a[0]||(a[0]=[n('<div><h1 id="hj57-高精度整数加法" tabindex="-1">HJ57 高精度整数加法 <a class="header-anchor" href="#hj57-高精度整数加法" aria-label="Permalink to &quot;HJ57 高精度整数加法&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ57 高精度整数加法”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：35.40% 时间限制：1秒 空间限制：32M 知识点==字符串== <strong>描述</strong> 输入两个用字符串 str 表示的整数，求它们所表示的数之和。 数据范围： 1≤���(���)≤10000 1≤<em>len</em>(<em>str</em>)≤10000 <strong>输入描述：</strong> 输入两个字符串。保证字符串只含有&#39;0&#39;~&#39;9&#39;字符 <strong>输出描述：</strong> 输出求和后的结果 <strong>示例1</strong> 输入： 98765432101234567890 ==复制== 输出： 11111111100 ==复制==</p></blockquote><p>这个问题可以通过模拟数字加法的过程来解决，尤其是当我们需要处理超出常规整数范围的大数时。具体方法是将两个字符串从尾部开始，即最低位开始逐位相加，记录进位，然后将结果以字符串形式输出。这种方法不受编程语言内置整数类型大小的限制。</p><p>以下是一个实现的步骤：</p><ol><li>首先，将两个输入字符串反转，这样字符串的开始位置就表示数字的最低位。</li><li>然后，逐位进行加法运算。如果某一位的计算结果超过9，则记录进位值（进位值要么是0，要么是1，因为两个数字相加最多只能产生1的进位）。</li><li>将每一步的计算结果（考虑进位）转换为字符串，并添加到结果字符串中。</li><li>如果最后还有进位，需要将进位也添加到结果字符串中。</li><li>最后，将结果字符串反转回来，得到最终的求和结果。</li></ol><p>这里给出一个相应的Python代码示例：</p><p>def addStrings(num1, num2):</p><h1 id="反转两个字符串-使得最低位在前" tabindex="-1">反转两个字符串，使得最低位在前 <a class="header-anchor" href="#反转两个字符串-使得最低位在前" aria-label="Permalink to &quot;反转两个字符串，使得最低位在前&quot;">​</a></h1><p>num1, num2 = num1[::-1], num2[::-1] carry = 0 result = []</p><h1 id="遍历较长数字的每一位" tabindex="-1">遍历较长数字的每一位 <a class="header-anchor" href="#遍历较长数字的每一位" aria-label="Permalink to &quot;遍历较长数字的每一位&quot;">​</a></h1><p>for i in range(max(len(num1), len(num2))): n1 = int(num1[i]) if i &lt; len(num1) else 0 n2 = int(num2[i]) if i &lt; len(num2) else 0</p><h1 id="计算当前位的总和加上前一位的进位" tabindex="-1">计算当前位的总和加上前一位的进位 <a class="header-anchor" href="#计算当前位的总和加上前一位的进位" aria-label="Permalink to &quot;计算当前位的总和加上前一位的进位&quot;">​</a></h1><p>total = n1 + n2 + carry</p><h1 id="计算当前位的值和新的进位" tabindex="-1">计算当前位的值和新的进位 <a class="header-anchor" href="#计算当前位的值和新的进位" aria-label="Permalink to &quot;计算当前位的值和新的进位&quot;">​</a></h1><p>carry = total // 10 result.append(str(total % 10))</p><h1 id="如果最后还有进位-添加到结果中" tabindex="-1">如果最后还有进位，添加到结果中 <a class="header-anchor" href="#如果最后还有进位-添加到结果中" aria-label="Permalink to &quot;如果最后还有进位，添加到结果中&quot;">​</a></h1><p>if carry: result.append(str(carry))</p><h1 id="将结果反转回正常的顺序并转换为字符串" tabindex="-1">将结果反转回正常的顺序并转换为字符串 <a class="header-anchor" href="#将结果反转回正常的顺序并转换为字符串" aria-label="Permalink to &quot;将结果反转回正常的顺序并转换为字符串&quot;">​</a></h1><p>return &quot;&quot;.join(result[::-1])</p><h1 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h1><p>num1 = input() num2 = input() print(addStrings(num1, num2))</p><p>这段代码能够处理包含数千位数字的字符串加法，而不会遇到整数溢出问题。</p></div>',1)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
